===================================================================
--- index.html
+++ index.html
@@ -17,6 +17,32 @@
 <div class="mobile" id="mobile"><div class="pad"><span></span><button class="touchbtn" data-key="w">▲</button><span></span><button class="touchbtn" data-key="a">◀</button><button class="touchbtn" data-key="s">▼</button><button class="touchbtn" data-key="d">▶</button></div><div class="actions"><button class="touchbtn" data-key="q">Q</button><button class="touchbtn" data-key="t">ERA</button><button class="touchbtn" data-key="e">E</button><button class="touchbtn" id="castTouch">✦</button></div></div>
 <div class="overlay" id="intro"><div class="card"><div class="kicker">A TIME-BENT OPEN-WORLD RPG</div><h2>BLACKWATER<br><span>AFTER</span> TIME</h2><p>1648. A witch-hunter's city, a stolen starship, and a tear in the hours. Fight the Crown's wraiths, claim three chronoshards, and decide which age inherits this world.</p><button class="start" id="start">ENTER THE RIFT &nbsp; →</button><span class="hint">WASD to move · click to cast · E to ride</span></div></div>
 <script type="module">
 import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
-</script>
+const scene=new THREE.Scene();scene.background=new THREE.Color(0x101c25);scene.fog=new THREE.FogExp2(0x101c25,.012);
+const camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,.1,240);
+const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;document.body.prepend(renderer.domElement);
+scene.add(new THREE.HemisphereLight(0xb5d5e0,0x211a1b,2.1));const moon=new THREE.DirectionalLight(0xffc88e,3.2);moon.position.set(-25,40,20);moon.castShadow=true;moon.shadow.mapSize.set(2048,2048);moon.shadow.camera.left=-55;moon.shadow.camera.right=55;moon.shadow.camera.top=55;moon.shadow.camera.bottom=-55;scene.add(moon);
+const mats={stone:new THREE.MeshStandardMaterial({color:0x53504a,roughness:.96}),darkstone:new THREE.MeshStandardMaterial({color:0x292d30,roughness:.9}),roof:new THREE.MeshStandardMaterial({color:0x44333a,roughness:.85}),wood:new THREE.MeshStandardMaterial({color:0x49352c,roughness:.85}),gold:new THREE.MeshStandardMaterial({color:0xb88047,metalness:.25,roughness:.55}),cyan:new THREE.MeshStandardMaterial({color:0x5de6e2,emissive:0x27aaa9,emissiveIntensity:2,roughness:.25}),warm:new THREE.MeshStandardMaterial({color:0xffbc68,emissive:0xff8a30,emissiveIntensity:2}),water:new THREE.MeshStandardMaterial({color:0x142a37,metalness:.45,roughness:.3}),ground:new THREE.MeshStandardMaterial({color:0x383b38,roughness:1}),grass:new THREE.MeshStandardMaterial({color:0x243b35,roughness:1})};
+const box=(x,y,z,mat,px,py,pz,shadow=true)=>{const m=new THREE.Mesh(new THREE.BoxGeometry(x,y,z),mat);m.position.set(px,py,pz);m.castShadow=shadow;m.receiveShadow=true;scene.add(m);return m};
+const cylinder=(r1,r2,h,mat,x,y,z,segments=8)=>{let m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m};
+const ground=box(180,.5,180,mats.ground,0,-.28,0,false);
+// canal and old-town stone quay
+const canal=box(27,.05,110,mats.water,-52,-.01,0,false);for(let z=-49;z<52;z+=7){box(2,.25,.25,mats.gold,-38,.04,z,false)}
+// cross-plaza paving and lane markings
+for(let x=-42;x<44;x+=4)for(let z=-42;z<44;z+=4){if(Math.abs(x)>1||Math.abs(z)>1)box(3.92,.025,3.92,((Math.floor(x/4)+Math.floor(z/4))%3===0?mats.darkstone:mats.stone),x,-.015,z,false)}
+// Town blocks: buildings are intentionally walkable-clear around plaza
+function building(x,z,w,d,h,kind=0){const wall=kind===2?new THREE.MeshStandardMaterial({color:0x283941,roughness:.8}):new THREE.MeshStandardMaterial({color:kind===1?0x57443a:0x62584d,roughness:.94});box(w,h,d,wall,x,h/2,z);const roofMat=kind===2?mats.darkstone:mats.roof;let roof=new THREE.Mesh(new THREE.ConeGeometry(Math.max(w,d)*.72,Math.min(w,d)*.5,4),roofMat);roof.position.set(x,h+.1,z);roof.rotation.y=Math.PI/4;roof.scale.set(w/Math.max(w,d),1,d/Math.max(w,d));roof.castShadow=true;scene.add(roof);
+for(let yy=2.1;yy<h-1;yy+=2.6){for(let xx=-w/2+1.5;xx<w/2-1;xx+=3){let win=box(.85,1.25,.12,kind===2?mats.cyan:mats.warm,x+xx,yy,z-d/2-.07,false);if(kind===2)win.material=mats.cyan;}}
+box(w+.25,.22,d+.25,mats.wood,x,.3,z);}
+// perimeter neighborhoods, docks and industrial future wreck
+building(-25,-26,14,12,12,0);building(-9,-27,12,13,16,1);building(11,-27,15,12,11,0);building(29,-26,13,14,15,0);building(-28,-7,11,14,14,1);building(29,-7,12,14,12,0);building(-29,14,13,14,11,0);building(29,15,13,13,16,1);building(-24,34,17,12,14,0);building(-5,34,13,12,10,1);building(14,34,16,12,17,2);building(32,34,12,12,13,0);building(49,-23,18,24,17,2);building(49,4,18,24,19,2);building(49,32,18,24,16,2);
+// distant silhouettes
+for(let i=0;i<32;i++){let x=(i%8)*15-55,z=Math.floor(i/8)*17-70;if(Math.abs(x)<40&&Math.abs(z)<40)continue;let hh=8+Math.random()*18;box(10,hh,11,new THREE.MeshStandardMaterial({color:0x222c32}),x,hh/2,z,false)}
+// gas lamps and crates
+for(const [x,z] of [[-18,-12],[18,-13],[-18,16],[18,18],[-5,24],[7,-2]]){cylinder(.13,.18,4,mats.darkstone,x,2,z);cylinder(.55,.35,.32,mats.warm,x,4.05,z);let glow=new THREE.PointLight(0xffa45d,18,10);glow.position.set(x,4.2,z);scene.add(glow)}
+for(const [x,z] of [[-8,11],[9,13],[-12,-16],[12,-18]]){box(1.7,1.6,1.7,mats.wood,x,.8,z);box(1.8,.14,1.8,mats.gold,x,1.62,z)}
+// Starfall portal, chronoshard pickups
+const portal=new THREE.Group();portal.position.set(0,0,-34);scene.add(portal);let ring=new THREE.Mesh(new THREE.TorusGeometry(4.5,.28,12,48),mats.cyan);ring.position.y=5;portal.add(ring);let inner=new THREE.Mesh(new THREE.CircleGeometry(4.2,48),new THREE.MeshBasicMaterial({color:0x194f60,transparent:true,opacity:.43,side:THREE.DoubleSide}));inner.position.y=5;portal.add(inner);let ring2=new THREE.Mesh(new THREE.TorusGeometry(3.4,.09,8,40),mats.warm);ring2.position.y=5;portal.add(ring2);for(let i=0;i<7;i++){let p=cylinder(.12,.12,6,mats.gold,0,0,0,6);p.position.set(Math.sin(i/7*Math.PI*2)*4.5,5+Math.cos(i/7*Math.PI*2)*4.5,0);portal.add(p)}
+const shardObjects=[];for(const [x,z] of [[-15,-1],[15,3],[1,24]]){let gem=new THREE.Mesh(new THREE.OctahedronGeometry(.7),mats.cyan);gem.position.set(x,1.25,z);gem.castShadow=true;scene.add(gem);let light=new THREE.PointLight(0x43cbd4,4,7);light.position.copy(gem.position);scene.add(light);shardObjects.push({mesh:gem,light,got:false})}
+
