// Player character: long-coat witchfinder with a glowing spell hand
const player=new THREE.Group();scene.add(player);const coat=new THREE.MeshStandardMaterial({color:0x273945,roughness:.72}),skin=new THREE.MeshStandardMaterial({color:0xc4916b}),cloth=new THREE.MeshStandardMaterial({color:0xd9c7a2,roughness:.8});
const torso=new THREE.Mesh(new THREE.CylinderGeometry(.42,.58,1.35,7),coat);torso.position.y=1.1;torso.castShadow=true;player.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.31,10,8),skin);head.position.y=2;head.castShadow=true;player.add(head);const hat=new THREE.Mesh(new THREE.CylinderGeometry(.14,.55,.18,8),mats.darkstone);hat.position.y=2.28;player.add(hat);const hatTop=new THREE.Mesh(new THREE.CylinderGeometry(.22,.22,.5,8),mats.darkstone);hatTop.position.y=2.58;hatTop.rotation.z=-.1;player.add(hatTop);const arm=new THREE.Mesh(new THREE.CylinderGeometry(.12,.16,.75,7),coat);arm.position.set(.5,1.25,-.08);arm.rotation.z=-.45;player.add(arm);const hand=new THREE.Mesh(new THREE.SphereGeometry(.16,8,8),mats.cyan);hand.position.set(.72,1.08,-.1);player.add(hand);const legs=[];for(const x of [-.22,.22]){let leg=new THREE.Mesh(new THREE.CylinderGeometry(.13,.16,.75,7),mats.darkstone);leg.position.set(x,.38,0);player.add(leg);legs.push(leg)}
// 17th-century motorcar and a crashed starship; both are driveable
function makeCar(x,z){let g=new THREE.Group();g.position.set(x,0,z);scene.add(g);let body=new THREE.Mesh(new THREE.BoxGeometry(2.4,.85,4),new THREE.MeshStandardMaterial({color:0x783c30,metalness:.2,roughness:.55}));body.position.y=.9;body.castShadow=true;g.add(body);let cabin=new THREE.Mesh(new THREE.BoxGeometry(1.7,.8,1.75),mats.wood);cabin.position.set(0,1.65,-.25);g.add(cabin);for(let xx of [-1,1])for(let zz of [-1.35,1.35]){let w=new THREE.Mesh(new THREE.CylinderGeometry(.42,.42,.24,12),new THREE.MeshStandardMaterial({color:0x151719}));w.rotation.z=Math.PI/2;w.position.set(xx, .48, zz);g.add(w)}for(let xx of [-.75,.75]){let l=new THREE.Mesh(new THREE.BoxGeometry(.4,.25,.08),mats.warm);l.position.set(xx,1,-2.02);g.add(l)}return g}
function makeShip(x,z){let g=new THREE.Group();g.position.set(x,0,z);scene.add(g);let hull=new THREE.Mesh(new THREE.ConeGeometry(1.65,5,6),new THREE.MeshStandardMaterial({color:0x324a55,metalness:.65,roughness:.3}));hull.rotation.x=Math.PI/2;hull.position.y=1.2;g.add(hull);let cockpit=new THREE.Mesh(new THREE.SphereGeometry(.72,12,8),new THREE.MeshStandardMaterial({color:0x55d6df,emissive:0x166c77,emissiveIntensity:1,transparent:true,opacity:.8}));cockpit.scale.set(1,.7,1.1);cockpit.position.set(0,1.9,-.35);g.add(cockpit);for(let x of [-1.25,1.25]){let wing=new THREE.Mesh(new THREE.BoxGeometry(1.2,.12,2.1),mats.darkstone);wing.position.set(x,1.1,.4);g.add(wing);let engine=cylinder(.32,.45,.8,mats.cyan,x,1.1,1.45,10);engine.rotation.x=Math.PI/2;g.add(engine)}return g}
const car=makeCar(8,9),ship=makeShip(22,28);const vehicles=[{mesh:car,name:'CROWN MOTORCAR',speed:14,turn:2.2},{mesh:ship,name:'STARFALL SKIFF',speed:22,turn:1.55}];
// enemies have readable silhouettes, health bars, and pursue the player
const enemies=[];function makeEnemy(x,z){let g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const robe=new THREE.Mesh(new THREE.ConeGeometry(.65,1.7,7),new THREE.MeshStandardMaterial({color:0x30222c,emissive:0x250e18,roughness:.8}));robe.position.y=.9;robe.castShadow=true;g.add(robe);let mask=new THREE.Mesh(new THREE.SphereGeometry(.32,8,7),new THREE.MeshStandardMaterial({color:0xd7b98e,emissive:0x3f2611}));mask.position.y=1.8;g.add(mask);for(let dx of [-.12,.12]){let eye=new THREE.Mesh(new THREE.SphereGeometry(.055),mats.warm);eye.position.set(dx,1.83,-.27);g.add(eye)}let bar=new THREE.Group();bar.position.y=2.3;g.add(bar);let back=new THREE.Mesh(new THREE.PlaneGeometry(1,.08),new THREE.MeshBasicMaterial({color:0x291b1c,side:THREE.DoubleSide}));bar.add(back);let fill=new THREE.Mesh(new THREE.PlaneGeometry(.96,.055),new THREE.MeshBasicMaterial({color:0xe75d50,side:THREE.DoubleSide}));fill.position.z=.01;bar.add(fill);let light=new THREE.PointLight(0xb53358,1.4,4);light.position.y=1.4;g.add(light);let e={mesh:g,hp:3,max:3,bar:fill,attack:0,alive:true,speed:1.7+Math.random()*.55,home:new THREE.Vector3(x,0,z)};enemies.push(e);return e}
for(const [x,z] of [[-21,2],[22,-18],[-13,26],[4,16],[31,8],[-31,-18],[13,-31]])makeEnemy(x,z);
// input, world state, and HUD
const keys={};let yaw=0,health=100,mana=100,shards=0,activeVehicle=null,started=false,eraFuture=false,elapsed=0,attackCooldown=0,dodge=0;let lastAction=0;const projectiles=[],fx=[];
const $=id=>document.getElementById(id);function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2100)}
function updateBars(){$('healthNum').textContent=Math.ceil(health);$('healthBar').style.width=Math.max(0,health)+'%';$('manaNum').textContent=Math.ceil(mana);$('manaBar').style.width=Math.max(0,mana)+'%';$('shardCount').textContent=shards+' / 3'}
function setEra(){eraFuture=!eraFuture;scene.background.set(eraFuture?0x0b2530:0x101c25);scene.fog.color.set(eraFuture?0x0b2530:0x101c25);moon.color.set(eraFuture?0x74e9ef:0xffc88e);$('era').innerHTML=eraFuture?'◈ &nbsp; 2284 — THE FRACTURED AGE':'◈ &nbsp; 1648 — THE OLD WORLD';$('era').style.color=eraFuture?'#68e4e6':'#f3bd72';toast(eraFuture?'TIME SHIFTED · FUTURE':'TIME SHIFTED · 1648');}
function targetPosition(){return activeVehicle?activeVehicle.mesh.position:player.position}
function fire(power=false){if(!started||activeVehicle)return;if(power){if(mana<30){toast('NOT ENOUGH ETHER');return}mana-=30}else{if(mana<5)return;mana-=5}updateBars();const from=new THREE.Vector3(player.position.x,.95,player.position.z);const direction=new THREE.Vector3(Math.sin(yaw),0,-Math.cos(yaw));if(power){for(let e of enemies)if(e.alive&&e.mesh.position.distanceTo(player.position)<9){e.hp-=2;e.mesh.material;damageEnemy(e,2)}effect(from,0x55e6e9,4);toast('CHRONO BURST')}else{const orb=new THREE.Mesh(new THREE.SphereGeometry(.2,8,8),new THREE.MeshBasicMaterial({color:0x79f5ff}));orb.position.copy(from).add(direction.clone().multiplyScalar(1));scene.add(orb);projectiles.push({mesh:orb,vel:direction.multiplyScalar(28),life:1.5,damage:1});}}
function effect(pos,color,size){let m=new THREE.Mesh(new THREE.SphereGeometry(.25,8,8),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8}));m.position.copy(pos);scene.add(m);fx.push({mesh:m,life:.45,max:.45,size})}
function damageEnemy(e,n){if(!e.alive)return;e.hp-=n;e.bar.scale.x=Math.max(0,e.hp/e.max);if(e.hp<=0){e.alive=false;scene.remove(e.mesh);let spark=new THREE.Mesh(new THREE.IcosahedronGeometry(.6,1),mats.warm);spark.position.set(e.mesh.position.x,.8,e.mesh.position.z);scene.add(spark);fx.push({mesh:spark,life:.8,max:.8,size:2});toast('WRAITH BANISHED');if(enemies.every(v=>!v.alive))$('objective').textContent='The watch is broken. Claim the chronoshards.'}}
function enterVehicle(){if(activeVehicle){player.position.copy(activeVehicle.mesh.position);player.position.y=0;activeVehicle=null;toast('ON FOOT');return}let nearest=vehicles.map(v=>({v,d:v.mesh.position.distanceTo(player.position)})).sort((a,b)=>a.d-b.d)[0];if(nearest.d<5){activeVehicle=nearest.v;toast('DRIVING · '+activeVehicle.name)}else toast('NO VEHICLE NEARBY')}

