// Start, keyboard, mouse aim, and touch controls
player.position.set(0,0,14);$('start').addEventListener('click',()=>{$('intro').style.opacity='0';setTimeout(()=>$('intro').style.display='none',650);started=true;renderer.domElement.requestPointerLock?.();toast('Find the rift · collect 3 chronoshards')});
document.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.repeat)return;let k=e.key.toLowerCase();if(k==='e')enterVehicle();if(k==='q')fire(true);if(k==='t')setEra();if(k===' '&&!activeVehicle){dodge=.35;mana=Math.min(100,mana+5)}if(k==='r'){let d=player.position.distanceTo(portal.position);if(d<8){if(shards>=3){winGame()}else toast('THE RIFT NEEDS '+(3-shards)+' MORE CHRONOSHARD'+(shards===2?'':'S'))}}});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement)yaw-=e.movementX*.0025});renderer.domElement.addEventListener('click',()=>{if(started&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.();if(started)fire(false)});
for(const b of document.querySelectorAll('[data-key]')){const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;if(k==='q')fire(true);if(k==='t')setEra();if(k==='e')enterVehicle()});for(const ev of ['pointerup','pointercancel','pointerleave'])b.addEventListener(ev,()=>keys[k]=false)}$('castTouch').addEventListener('pointerdown',e=>{e.preventDefault();fire(false)});
function winGame(){started=false;$('intro').style.display='grid';$('intro').style.opacity='1';document.querySelector('.kicker').textContent='THE RIFT IS YOURS';document.querySelector('.card h2').innerHTML='TIME IS<br><span>YOURS</span> NOW';document.querySelector('.card p').textContent='The chronoshards sing in unison. Blackwater folds across centuries, and the future is yours to shape. You escaped the watch.';$('start').textContent='PLAY AGAIN';$('start').onclick=()=>location.reload()}
function clampWorld(p){p.x=THREE.MathUtils.clamp(p.x,-42,42);p.z=THREE.MathUtils.clamp(p.z,-44,44)}
function damagePlayer(n){if(dodge>0)return;health=Math.max(0,health-n);updateBars();if(health<=0){health=100;player.position.set(0,0,14);if(activeVehicle){activeVehicle=null}updateBars();toast('YOU FELL · THE RIFT RESTORES YOU')}}
const clock=new THREE.Clock();function tick(){requestAnimationFrame(tick);const dt=Math.min(clock.getDelta(),.04);elapsed+=dt;
